-- ===== Module: Controls (Modules/Controls.luau) =====
__factories["Controls"] = (function()
-- SpeedHubX / Modules / Controls.luau
-- Section / Toggle / Dropdown / Slider / Button / Paragraph factories.
--
-- Controls are pure UI: they keep their own value, repaint themselves and
-- invoke the supplied callback. Callbacks in this package are the empty
-- stubs from Modules/Features.luau, so controls never touch gameplay.
--
-- Every factory returns a handle: { Value, Set(value, fireCallback?), Frame }.

export type ToggleOptions = {
	Title: string,
	Description: string?,
	Default: boolean?,
	Callback: ((boolean) -> ())?,
}
export type DropdownOptions = {
	Title: string,
	Options: { string },
	Default: string?,
	Callback: ((string) -> ())?,
}
export type SliderOptions = {
	Title: string,
	Description: string?,
	Min: number,
	Max: number,
	Default: number?,
	Step: number?,
	Format: ((number) -> string)?,
	Callback: ((number) -> ())?,
}
export type ButtonOptions = {
	Title: string,
	Description: string?,
	Callback: (() -> ())?,
}

return function(Deps: any)
	local Theme = Deps.Theme
	local Util = Deps.Util
	local Bucket = Deps.Bucket
	local new = Util.new

	local Controls = {}

	local function corner(radius: number): UICorner
		return new("UICorner", { CornerRadius = UDim.new(0, radius) }) :: UICorner
	end

	-- Shared dark card shell used by Toggle / Slider / Button / Paragraph.
	local function card(parent: Instance, height: number): Frame
		local frame = new("Frame", {
			Name = "Card",
			BackgroundColor3 = Theme.Color.Card,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, height),
			Parent = parent,
		}) :: Frame
		corner(Theme.Metric.CardCorner).Parent = frame
		return frame
	end

	local function titleAndDescription(
		parent: Instance,
		title: string,
		description: string?
	): (TextLabel, TextLabel?)
		local titleLabel = new("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, description and 10 or 0),
			Size = UDim2.new(1, -76, 0, 22),
			Font = Theme.Font.Label,
			TextSize = Theme.TextSize.Label,
			TextColor3 = Theme.Color.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = description and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
			Text = title,
			Parent = parent,
		}) :: TextLabel
		if not description then
			titleLabel.Size = UDim2.new(1, -76, 1, 0)
			return titleLabel, nil
		end
		local descriptionLabel = new("TextLabel", {
			Name = "Description",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, 34),
			Size = UDim2.new(1, -76, 0, 18),
			Font = Theme.Font.Description,
			TextSize = Theme.TextSize.Description,
			TextColor3 = Theme.Color.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			Text = description,
			Parent = parent,
		}) :: TextLabel
		return titleLabel, descriptionLabel
	end

	--- Section header, e.g. "Skill" / "Aim" / "Body".
	function Controls.Section(parent: Instance, text: string): TextLabel
		local label = new("TextLabel", {
			Name = "Section",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 36),
			Font = Theme.Font.Section,
			TextSize = Theme.TextSize.Section,
			TextColor3 = Theme.Color.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Bottom,
			Text = text,
			Parent = parent,
		}) :: TextLabel
		return label
	end

	--- Toggle row: dark card, title/description on the left and a square
	--- track with a red dot (on) / grey dot (off) on the right, as in the
	--- reference image. The whole card is clickable.
	function Controls.Toggle(parent: Instance, options: ToggleOptions): any
		local value = options.Default == true

		local button = new("TextButton", {
			Name = "Toggle_" .. options.Title,
			AutoButtonColor = false,
			BackgroundColor3 = Theme.Color.Card,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, Theme.Metric.CardHeight),
			Text = "",
			Parent = parent,
		}) :: TextButton
		corner(Theme.Metric.CardCorner).Parent = button
		titleAndDescription(button, options.Title, options.Description)

		local size = Theme.Metric.ToggleSize
		local track = new("Frame", {
			Name = "Track",
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundColor3 = Theme.Color.ValueBox,
			BorderSizePixel = 0,
			Position = UDim2.new(1, -14, 0.5, 0),
			Size = UDim2.fromOffset(size, size),
			Parent = button,
		}) :: Frame
		corner(8).Parent = track

		local knob = new("Frame", {
			Name = "Knob",
			AnchorPoint = Vector2.new(0.5, 0.5),
			BorderSizePixel = 0,
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(18, 18),
			Parent = track,
		}) :: Frame
		corner(9).Parent = knob

		local handle: any = {}

		local function repaint()
			knob.BackgroundColor3 = value and Theme.Color.IndicatorOn or Theme.Color.KnobOff
		end

		function handle.Set(newValue: boolean, fireCallback: boolean?)
			value = newValue == true
			handle.Value = value
			repaint()
			if fireCallback and options.Callback then
				options.Callback(value)
			end
		end

		function handle.Get(): boolean
			return value
		end

		handle.Value = value
		handle.Frame = button

		Bucket:add(button.MouseButton1Click:Connect(function()
			handle.Set(not value, true)
			handle.Value = value
		end))
		Bucket:add(button.MouseEnter:Connect(function()
			button.BackgroundColor3 = Theme.Color.CardHover
		end))
		Bucket:add(button.MouseLeave:Connect(function()
			button.BackgroundColor3 = Theme.Color.Card
		end))

		repaint()
		return handle
	end

	--- Dropdown row: label on the left, caret, and a wide value box on the
	--- right ("Head" in the reference image). Clicking expands the option
	--- list directly under the row. Selection is UI state only.
	function Controls.Dropdown(parent: Instance, options: DropdownOptions): any
		local value = options.Default or options.Options[1] or ""

		local container = new("Frame", {
			Name = "Dropdown_" .. options.Title,
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, Theme.Metric.DropdownHeight),
			Parent = parent,
		}) :: Frame
		new("UIListLayout", {
			Padding = UDim.new(0, 6),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = container,
		})

		local row = new("TextButton", {
			Name = "Row",
			AutoButtonColor = false,
			BackgroundColor3 = Theme.Color.Card,
			BorderSizePixel = 0,
			LayoutOrder = 1,
			Size = UDim2.new(1, 0, 0, Theme.Metric.DropdownHeight),
			Text = "",
			Parent = container,
		}) :: TextButton
		corner(Theme.Metric.CardCorner).Parent = row

		new("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, 0),
			Size = UDim2.new(0.45, 0, 1, 0),
			Font = Theme.Font.Label,
			TextSize = Theme.TextSize.Label,
			TextColor3 = Theme.Color.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = options.Title,
			Parent = row,
		})

		local caret = new("TextLabel", {
			Name = "Caret",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -296, 0.5, 0),
			Size = UDim2.fromOffset(24, 24),
			Font = Theme.Font.Label,
			TextSize = 18,
			TextColor3 = Theme.Color.TextDim,
			Text = "^",
			Parent = row,
		}) :: TextLabel

		local valueBox = new("Frame", {
			Name = "ValueBox",
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundColor3 = Theme.Color.ValueBox,
			BorderSizePixel = 0,
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.new(0, 272, 0, 38),
			Parent = row,
		}) :: Frame
		corner(6).Parent = valueBox

		local valueLabel = new("TextLabel", {
			Name = "Value",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Font = Theme.Font.Value,
			TextSize = Theme.TextSize.Value,
			TextColor3 = Theme.Color.Text,
			Text = value,
			Parent = valueBox,
		}) :: TextLabel

		local list = new("Frame", {
			Name = "Options",
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = Theme.Color.Card,
			BorderSizePixel = 0,
			LayoutOrder = 2,
			Size = UDim2.new(1, 0, 0, 0),
			Visible = false,
			Parent = container,
		}) :: Frame
		corner(Theme.Metric.CardCorner).Parent = list
		new("UIListLayout", {
			Padding = UDim.new(0, 2),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = list,
		})
		new("UIPadding", {
			PaddingTop = UDim.new(0, 6),
			PaddingBottom = UDim.new(0, 6),
			PaddingLeft = UDim.new(0, 8),
			PaddingRight = UDim.new(0, 8),
			Parent = list,
		})

		local handle: any = {}
		local open = false

		local function repaint()
			valueLabel.Text = value
			list.Visible = open
			caret.Text = open and "v" or "^"
		end

		function handle.Set(newValue: string, fireCallback: boolean?)
			value = newValue
			repaint()
			if fireCallback and options.Callback then
				options.Callback(value)
			end
		end

		function handle.Get(): string
			return value
		end

		handle.Frame = container

		for index, option in ipairs(options.Options) do
			local optionButton = new("TextButton", {
				Name = "Option_" .. option,
				AutoButtonColor = false,
				BackgroundColor3 = Theme.Color.ValueBox,
				BorderSizePixel = 0,
				LayoutOrder = index,
				Size = UDim2.new(1, 0, 0, 34),
				Font = Theme.Font.Label,
				TextSize = Theme.TextSize.Label,
				TextColor3 = Theme.Color.TextDim,
				Text = option,
				Parent = list,
			}) :: TextButton
			corner(6).Parent = optionButton
			Bucket:add(optionButton.MouseButton1Click:Connect(function()
				open = false
				handle.Set(option, true)
			end))
		end

		Bucket:add(row.MouseButton1Click:Connect(function()
			open = not open
			repaint()
		end))

		repaint()
		return handle
	end

	--- Slider row (reusable component; used by the Misc tab for the menu's
	--- own scale setting). Supports mouse and touch; value is UI state only.
	function Controls.Slider(parent: Instance, options: SliderOptions): any
		local minimum = options.Min
		local maximum = options.Max
		local step = options.Step or 1
		local value = math.clamp(options.Default or minimum, minimum, maximum)

		local frame = card(parent, 78)
		frame.Name = "Slider_" .. options.Title
		titleAndDescription(frame, options.Title, options.Description)

		local valueLabel = new("TextLabel", {
			Name = "Value",
			AnchorPoint = Vector2.new(1, 0),
			BackgroundTransparency = 1,
			Position = UDim2.new(1, -16, 0, 10),
			Size = UDim2.fromOffset(90, 22),
			Font = Theme.Font.Value,
			TextSize = 16,
			TextColor3 = Theme.Color.Text,
			TextXAlignment = Enum.TextXAlignment.Right,
			Parent = frame,
		}) :: TextLabel

		local bar = new("Frame", {
			Name = "Bar",
			BackgroundColor3 = Theme.Color.ValueBox,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 16, 1, -24),
			Size = UDim2.new(1, -32, 0, 6),
			Parent = frame,
		}) :: Frame
		corner(3).Parent = bar

		local fill = new("Frame", {
			Name = "Fill",
			BackgroundColor3 = Theme.Color.SliderFill,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(0, 1),
			Parent = bar,
		}) :: Frame
		corner(3).Parent = fill

		local knob = new("Frame", {
			Name = "Knob",
			AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = Theme.Color.Text,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.fromOffset(14, 14),
			Parent = bar,
		}) :: Frame
		corner(7).Parent = knob

		local hitbox = new("TextButton", {
			Name = "Hitbox",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 0, 0, -8),
			Size = UDim2.new(1, 0, 1, 16),
			Text = "",
			Parent = bar,
		}) :: TextButton

		local handle: any = {}
		local dragging = false

		local function format(v: number): string
			if options.Format then
				return options.Format(v)
			end
			return tostring(v)
		end

		local function repaint()
			local alpha = (value - minimum) / math.max(maximum - minimum, 0.0001)
			fill.Size = UDim2.fromScale(alpha, 1)
			knob.Position = UDim2.new(alpha, 0, 0.5, 0)
			valueLabel.Text = format(value)
		end

		function handle.Set(newValue: number, fireCallback: boolean?)
			local snapped = minimum + math.round((newValue - minimum) / step) * step
			value = math.clamp(snapped, minimum, maximum)
			repaint()
			if fireCallback and options.Callback then
				options.Callback(value)
			end
		end

		function handle.Get(): number
			return value
		end

		handle.Frame = frame

		local function setFromInput(input: InputObject)
			local alpha = math.clamp(
				(input.Position.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1),
				0,
				1
			)
			handle.Set(minimum + alpha * (maximum - minimum), true)
		end

		Bucket:add(hitbox.InputBegan:Connect(function(input: InputObject)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			then
				dragging = true
				setFromInput(input)
			end
		end))
		Bucket:add(Util.UserInputService.InputChanged:Connect(function(input: InputObject)
			if dragging
				and (input.UserInputType == Enum.UserInputType.MouseMovement
					or input.UserInputType == Enum.UserInputType.Touch)
			then
				setFromInput(input)
			end
		end))
		Bucket:add(Util.UserInputService.InputEnded:Connect(function(input: InputObject)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			then
				dragging = false
			end
		end))

		repaint()
		return handle
	end

	--- Full-width clickable card (no buttons are visible on the Main tab of
	--- the reference image; used on the Home tab for Hide / Unload).
	function Controls.Button(parent: Instance, options: ButtonOptions): any
		local button = new("TextButton", {
			Name = "Button_" .. options.Title,
			AutoButtonColor = false,
			BackgroundColor3 = Theme.Color.Card,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, Theme.Metric.CardHeight),
			Text = "",
			Parent = parent,
		}) :: TextButton
		corner(Theme.Metric.CardCorner).Parent = button
		titleAndDescription(button, options.Title, options.Description)
		new("TextLabel", {
			Name = "Chevron",
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundTransparency = 1,
			Position = UDim2.new(1, -16, 0.5, 0),
			Size = UDim2.fromOffset(20, 20),
			Font = Theme.Font.Label,
			TextSize = 18,
			TextColor3 = Theme.Color.TextMuted,
			Text = ">",
			Parent = button,
		})
		if options.Callback then
			Bucket:add(button.MouseButton1Click:Connect(options.Callback))
		end
		Bucket:add(button.MouseEnter:Connect(function()
			button.BackgroundColor3 = Theme.Color.CardHover
		end))
		Bucket:add(button.MouseLeave:Connect(function()
			button.BackgroundColor3 = Theme.Color.Card
		end))
		return { Frame = button }
	end

	--- Static info card.
	function Controls.Paragraph(parent: Instance, title: string, description: string): Frame
		local frame = card(parent, 62)
		frame.Name = "Paragraph_" .. title
		frame.AutomaticSize = Enum.AutomaticSize.Y
		titleAndDescription(frame, title, description)
		return frame
	end

	return Controls
end
end)()

-- ===== Module: Window (Modules/Window.luau) =====
__factories["Window"] = (function()
-- SpeedHubX / Modules / Window.luau
-- Core window builder + sidebar navigation.
--
-- Layout replicated from the reference image:
--   * 1020 x 640 near-black window, 10px corner, thin dark-red edge
--   * "Speed Hub X | Version: 3.7.0" top-left, X close button top-right
--   * 260px sidebar: Home / Main (selected, red) / Farming / Killer / Misc
--   * scrolling content area on the right, one page per sidebar tab

export type NavItem = {
	Name: string,
	Icon: string,
}
export type BuildOptions = {
	Parent: Instance,
	OnClose: (() -> ())?,
}

return function(Deps: any)
	local Theme = Deps.Theme
	local Util = Deps.Util
	local Bucket = Deps.Bucket
	local new = Util.new

	local Window = {}

	-- Text glyphs stand in for the image icons so the menu needs no
	-- external/uploaded assets (executor-safe, works in any place).
	Window.NavItems = {
		{ Name = "Home", Icon = "⊞" },
		{ Name = "Main", Icon = "⌂" },
		{ Name = "Farming", Icon = "⛏" },
		{ Name = "Killer", Icon = "☠" },
		{ Name = "Misc", Icon = "▤" },
	} :: { NavItem }

	function Window.Build(options: BuildOptions): any
		local screenGui = new("ScreenGui", {
			Name = Theme.GuiName,
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			AutoLocalize = false,
			DisplayOrder = 999,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		}) :: ScreenGui

		local scale = new("UIScale", { Scale = 1, Parent = screenGui }) :: UIScale

		local frame = new("Frame", {
			Name = "Window",
			AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = Theme.Color.Window,
			BorderSizePixel = 0,
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(Theme.Metric.WindowSize.X, Theme.Metric.WindowSize.Y),
			Parent = screenGui,
		}) :: Frame
		new("UICorner", {
			CornerRadius = UDim.new(0, Theme.Metric.WindowCorner),
			Parent = frame,
		})
		-- Thin dark-red edge visible on the right/bottom in the screenshot.
		new("UIStroke", {
			Color = Theme.Color.Edge,
			Thickness = 1,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			Parent = frame,
		})

		-- Title bar (also the drag handle)
		local titleBar = new("Frame", {
			Name = "TitleBar",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 76),
			Parent = frame,
		}) :: Frame

		new("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 26, 0, 0),
			Size = UDim2.new(1, -110, 1, 0),
			Font = Theme.Font.Title,
			TextSize = Theme.TextSize.Title,
			TextColor3 = Theme.Color.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = Theme.Title,
			Parent = titleBar,
		})

		local closeButton = new("TextButton", {
			Name = "Close",
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundTransparency = 1,
			Position = UDim2.new(1, -16, 0.5, 0),
			Size = UDim2.fromOffset(40, 40),
			Font = Theme.Font.Label,
			TextSize = 22,
			TextColor3 = Theme.Color.Text,
			Text = "✕",
			Parent = titleBar,
		}) :: TextButton

		-- Sidebar navigation
		local sidebar = new("Frame", {
			Name = "Sidebar",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, Theme.Metric.WindowPadding, 0, 92),
			Size = UDim2.new(0, Theme.Metric.SidebarWidth, 1, -112),
			Parent = frame,
		}) :: Frame
		new("UIListLayout", {
			Padding = UDim.new(0, Theme.Metric.NavButtonGap),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = sidebar,
		})

		-- Content host (pages are stacked ScrollingFrames)
		local contentX = Theme.Metric.WindowPadding + Theme.Metric.SidebarWidth + Theme.Metric.ContentGap
		local content = new("Frame", {
			Name = "Content",
			BackgroundTransparency = 1,
			Position = UDim2.new(0, contentX, 0, 84),
			Size = UDim2.new(1, -contentX - Theme.Metric.WindowPadding, 1, -104),
			Parent = frame,
		}) :: Frame

		local handle: any = {
			ScreenGui = screenGui,
			Frame = frame,
			Scale = scale,
			Pages = {},
			CurrentPage = nil,
		}

		local navButtons: { [string]: TextButton } = {}

		local function repaintNav()
			for name, button in pairs(navButtons) do
				local selected = name == handle.CurrentPage
				button.BackgroundColor3 = selected and Theme.Color.Accent or Theme.Color.NavIdle
				local label = button:FindFirstChild("Label") :: TextLabel?
				if label then
					label.TextColor3 = selected and Theme.Color.AccentText or Theme.Color.TextDim
				end
			end
			for name, page in pairs(handle.Pages) do
				(page :: ScrollingFrame).Visible = name == handle.CurrentPage
			end
		end

		--- Create (or fetch) the scrolling page for a tab.
		function handle.CreatePage(name: string): ScrollingFrame
			if handle.Pages[name] then
				return handle.Pages[name]
			end
			local page = new("ScrollingFrame", {
				Name = "Page_" .. name,
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				CanvasSize = UDim2.new(0, 0, 0, 0),
				ScrollBarImageColor3 = Theme.Color.ScrollBar,
				ScrollBarThickness = 3,
				Size = UDim2.fromScale(1, 1),
				Visible = false,
				Parent = content,
			}) :: ScrollingFrame
			new("UIListLayout", {
				Padding = UDim.new(0, Theme.Metric.CardGap),
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = page,
			})
			new("UIPadding", {
				PaddingRight = UDim.new(0, 4),
				PaddingBottom = UDim.new(0, 8),
				Parent = page,
			})
			handle.Pages[name] = page
			return page
		end

		function handle.SelectPage(name: string)
			if not handle.Pages[name] then
				return
			end
			handle.CurrentPage = name
			repaintNav()
		end

		for index, item in ipairs(Window.NavItems) do
			local button = new("TextButton", {
				Name = "Nav_" .. item.Name,
				AutoButtonColor = false,
				BackgroundColor3 = Theme.Color.NavIdle,
				BorderSizePixel = 0,
				LayoutOrder = index,
				Size = UDim2.new(1, 0, 0, Theme.Metric.NavButtonHeight),
				Text = "",
				Parent = sidebar,
			}) :: TextButton
			new("UICorner", {
				CornerRadius = UDim.new(0, 8),
				Parent = button,
			})
			new("TextLabel", {
				Name = "Label",
				BackgroundTransparency = 1,
				Position = UDim2.new(0, 14, 0, 0),
				Size = UDim2.new(1, -20, 1, 0),
				Font = Theme.Font.Label,
				TextSize = Theme.TextSize.Nav,
				TextColor3 = Theme.Color.TextDim,
				TextXAlignment = Enum.TextXAlignment.Left,
				Text = item.Icon .. "  |  " .. item.Name,
				Parent = button,
			})
			navButtons[item.Name] = button
			Bucket:add(button.MouseButton1Click:Connect(function()
				handle.SelectPage(item.Name)
			end))
			Bucket:add(button.MouseEnter:Connect(function()
				if handle.CurrentPage ~= item.Name then
					button.BackgroundColor3 = Theme.Color.NavHover
				end
			end))
			Bucket:add(button.MouseLeave:Connect(function()
				if handle.CurrentPage ~= item.Name then
					button.BackgroundColor3 = Theme.Color.NavIdle
				end
			end))
			handle.CreatePage(item.Name)
		end

		if options.OnClose then
			Bucket:add(closeButton.MouseButton1Click:Connect(options.OnClose))
		end

		-- Keep the fixed-size window usable on small viewports.
		local userScale = 1
		local function fitToViewport()
			local camera = workspace.CurrentCamera
			if not camera then
				return
			end
			local viewport = camera.ViewportSize
			local fit = math.min(
				viewport.X / (Theme.Metric.WindowSize.X + 40),
				viewport.Y / (Theme.Metric.WindowSize.Y + 40)
			)
			scale.Scale = math.clamp(fit, 0.55, 1) * userScale
		end
		handle.SetUserScale = function(value: number)
			userScale = math.clamp(value, 0.5, 1.2)
			fitToViewport()
		end
		fitToViewport()
		local camera = workspace.CurrentCamera
		if camera then
			Bucket:add(camera:GetPropertyChangedSignal("ViewportSize"):Connect(fitToViewport))
		end

		handle.SelectPage("Main")
		handle.RepaintNav = repaintNav

		local setDraggingEnabled = Util.makeDraggable(frame, titleBar, Bucket)
		handle.SetDraggingEnabled = setDraggingEnabled

		-- Safe parenting with fallback (gethui -> CoreGui -> PlayerGui).
		Util.protectGui(screenGui)
		local parent = Util.bestParent()
		if parent then
			pcall(function()
				screenGui.Parent = parent
			end)
		end
		if not screenGui.Parent then
			Util.parentGui(screenGui)
		end
		handle.ParentSource = screenGui.Parent and screenGui.Parent.Name or "none"

		return handle
	end

	return Window
end
end)()

